-- Read-only export (production). Patterns: sentiment_key in (neon_support_bounce, stealth_breakout, liquidation_cascade, price_led_momentum, impulse_buy), detected_at >= 2026-09-01.
select id, sentiment_key as pattern, symbol, detected_at,
