 coalesce(stop_loss_price, case when stop_loss_pct is not null then coalesce(original_entry_price, entry_price)*(1-stop_loss_pct/100.0) end) as stop_price,
 case when stop_loss_price is not null then 'stop_loss_price' when stop_loss_pct is not null then 'derived_from_stop_loss_pct' else 'missing' end as stop_src,
